static List<Product> searchProducts(Session s, String cat, Double min, Double max) {
    StringBuilder hql = new StringBuilder("from Product p where 1=1");
    if (cat != null) hql.append(" and p.category = :cat");
    if (min != null) hql.append(" and p.price >= :min");
    if (max != null) hql.append(" and p.price <= :max");
    var q = s.createQuery(hql.toString(), Product.class);
    if (cat != null) q.setParameter("cat", cat);
    if (min != null) q.setParameter("min", min);
    if (max != null) q.setParameter("max", max);
    return q.getResultList();
}

