// HQL operuje na nazwach klas/pol Java, SQL na nazwach tabel/kolumn bazy

static void validateAll(SessionFactory sf, List<String> queries) {
    try (Session s = sf.openSession()) {
        for (String hql : queries) {
            try { s.createQuery(hql); System.out.println("OK: " + hql); }
            catch (Exception e) { System.out.println("BLAD w: " + hql + " - " + e.getMessage()); }
        }
    }
}

